bp_safe; t=$(mktemp) || exit 1; { git "$@"; echo $? > "$t"; } | LC_ALL=C awk -v per=65536 -v max=131072 -v maxfiles=150 'function flush() { if (!infile) return; if (big) printf "%s@@ -0,0 +0,0 @@\n\\ Too big to show here: +%d -%d lines\n", head, adds, dels; else { printf "%s%s", head, body; total += size }; infile = 0; inbody = 0; head = ""; body = ""; big = 0; adds = 0; dels = 0; size = 0 } /^diff --git / { flush(); files++; if (files > maxfiles) { extra++; skip = 1; next }; infile = 1 } { if (skip) next; if (!infile) { print; next }; if (!inbody && substr($0, 1, 3) == "@@ ") inbody = 1; if (!inbody) { head = head $0 "\n"; next }; c = substr($0, 1, 1); if (c == "+") adds++; else if (c == "-") dels++; if (big) next; size += length($0) + 1; if (size > per || total + size > max) { big = 1; body = ""; next }; body = body $0 "\n" } END { flush(); if (extra) printf "\\ %d more changed files not shown here\n", extra }'; c=$(cat "$t"); rm -f "$t"; exit ${c:-1}